// DefaultTheme retourne le thème par défaut (Catppuccin Mocha)
func DefaultTheme() *Theme {
	return &Theme{
		Name:               "default",
		ColorOK:            "#a6e3a1",
		ColorError:         "#f38ba8",
		ColorWarn:          "#fab387",
		ColorPrimary:       "#cba6f7",
		ColorSecondary:     "#b4befe",
