		ColorText:          "#cdd6f4",
		ColorDim:           "#585b70",
		ColorHighlight:     "#f9e2af",
		ColorWhite:         "#cdd6f4",
		ColorBlack:         "#1e1e2e",
		ColorBackground:    "#1e1e2e",
		TitleFg:            "#cba6f7",
		AppTitleFg:         "#cba6f7",
		SubTitleFg:         "#b4befe",
		ButtonFg:           "#1e1e2e",
		ButtonBg:           "#cba6f7",
		ButtonInactiveFg:   "#cdd6f4",
		ButtonInactiveBg:   "#585b70",
		TabActiveFg:        "#1e1e2e",
		TabActiveBg:        "#b4befe",
		TabInactiveFg:      "#585b70",
		TabInactiveBg:      "#313244",
		TableHeaderFg:      "#b4befe",
		TableSelectedFg:    "#1e1e2e",
		TableSelectedBg:    "#b4befe",
