func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuildText()
		return m, cmd
	}

	switch msg.String() {
	case "esc":
		return m.goBack()
	case "f":
		m.toggleDisplay()
		return m, nil
	case "c":
		m.toggleHighlight()
		return m, nil
	case "ctrl+r":
		return m.reload()
