	case m.infoMsg != "":
		infoLine = highlightLine(m.infoMsg, width)
	case m.actionLine() != "":
		infoLine = highlightLine(m.actionLine(), width)
	}
	parts = append(parts, tabBar, theme.EmptyLineBg(width), infoLine)
	return strings.Join(parts, "\n")
}

